function makeCard(container, cardsData) {
  const card = document.createElement('div');
  card.className = 'disc-card';
  const title = document.createElement('div');
  title.className = 'disc-card__title';
  title.textContent = 'Я наиболее';
  const list = document.createElement('ul');
  list.className = 'disc-list';
  const foot = document.createElement('div');
  foot.className = 'disc-card__foot';
  foot.textContent = 'Я наименее';
  cardsData.forEach((item, i) => {
    const [type, label] = item;
    const li = document.createElement('li');
    li.className = 'disc-item';
    li.dataset.type = type;
    li.setAttribute('draggable','false');
    li.tabIndex = 0; // keyboard focus
    li.innerHTML = `<span class="rank" aria-hidden="true">1</span><span class="label"></span>`;
    li.querySelector('.label').textContent = label;
    list.appendChild(li);
  });
  // renumber
  function renumber(){
    [...list.children].forEach((li,i)=>{
      li.querySelector('.rank').textContent = i+1;
    });
  }
  renumber();
  card.appendChild(title);
  card.appendChild(list);
  card.appendChild(foot);
  container.appendChild(card);
  setupDrag(list);
}
```

