async function main() {
  let chrome;
  chrome = spawn('google-chrome', [
    '--headless', '--no-sandbox', '--disable-gpu',
    '--remote-debugging-port=9999',
    '--disable-dev-shm-usage',
    '--window-size=1400,900',
    PAGE
  ], { stdio: ['pipe','pipe','pipe'] });
  let stderr = '';
  chrome.stderr.on('data', b => { stderr += b.toString(); });
  chrome.stdout.on('data', b => {});

  // Parse the actual DevTools port from stderr
  let wsUrl = null;
  for (let i = 0; i < 40; i++) {
    await sleep(400);
    if (stderr) {
      const m = stderr.match(/DevTools listening on (ws:\/\/127\.0\.0\.1:(\d+))\/devtools\/browser\/[\w-]+/);
      if (m) {
        const port = m[2];
        const list = await getJSON('http://127.0.0.1:' + port + '/json/list');
        try {
          const arr = JSON.parse(list);
          const pageTarget = arr.find(a => a.type === 'page');
          if (pageTarget) { wsUrl = pageTarget.debuggingProtocolUrl; break; }
        } catch(e){}
      }
    }
  }
  if (!wsUrl) { chrome.kill(); console.log('NO CDP TARGET: ' + stderr.slice(0,800)); process.exit(1); }

  const ws = new WebSocket(wsUrl);
  let id = 1;
  const pending = {};
  function send(cmd) {
    return new Promise((res, rej) => {
      const myId = id++;
      pending[myId] = { res, rej };
      ws.send(JSON.stringify({ id: myId, method: cmd.method, params: cmd.params || {} }));
    });
  }

  ws.onmessage = (ev) => {
    const msg = JSON.parse(ev.data);
    const p = pending[msg.id];
    if (p) p.res(msg);
    if (msg.error) console.log('CDP error', msg.error);
  };
  ws.onerror = e => console.log('ws error', e);

  await new Promise((r) => { ws.onopen = () => { send({method:'Page.enable'}).then(() => r()); }; });
  await send({ method: 'Runtime.enable' });
