      report.hidden = { start: document.getElementById('startScreen').hidden,
                         test: document.getElementById('testScreen').hidden,
                         result: document.getElementById('resultScreen').hidden };
      return report.hidden;
    };
    const btnDisp = (id) => {
      const b = document.getElementById(id);
      return b ? b.style.display : null;
    };
    document.getElementById('btnStart').click();
    report.afterStart = state();
    report.listCount = document.querySelectorAll('.disc-list').length;
    report.itemCount = document.querySelectorAll('.disc-item').length;
    report.itemTypes = {};
    for (const it of document.querySelectorAll('.disc-item')) {
      const t = it.dataset.type || '?';
      report.itemTypes[t] = (report.itemTypes[t] || 0) + 1;
    }
    await sleep(100);
    // advance to last step
    for (let s = 0; s < 8; s++) {
      const finishBtn = document.getElementById('btnFinish');
