const http = require('http');
function getJSON(u) {
  return new Promise((res, rej) => {
    const req = http.get(u, (r) => { const c = []; r.on('data', x => c.push(x)); r.on('end', () => res(Buffer.concat(c).toString())); r.on('error', rej); });
    req.on('error', rej);
  });
}
async function main() {
  const arr = JSON.parse(await getJSON('http://127.0.0.1:9999/json/list'));
  const pt = arr.find(a => a.type === 'page' && a.url.indexOf('index_final') >= 0);
  if (!pt) { console.log('NO PAGE TARGET: ' + JSON.stringify(arr.map(a=>a.type))); process.exit(1); }
  const ws = new WebSocket(pt.webSocketDebuggerUrl);
  await new Promise((r, j) => { ws.onopen = r; ws.onerror = j; ws.onclose = j; });
  let id = 1, pending = {};
  const send = (m, ms) => new Promise((res, rej) => {
    const myId = id++;
    const t = setTimeout(() => rej(new Error('timeout '+m.method)), ms);
    pending[myId] = { res: x => { clearTimeout(t); res(x); }, rej: x => { clearTimeout(t); rej(x); } };
    ws.send(JSON.stringify({ id: myId, method: m.method, params: m.params || {} }));
  });
  ws.onmessage = e => { const m = JSON.parse(e.data); const p = pending[m.id]; if (p) p.res(m); };
  const evalIn = (expr) => send({ method: 'Runtime.evaluate', params: { expression: expr, returnByValue: true }, 5000 }).then(r => r.result ? r.result.value : r.error ? { error: r.error.message } : 'ok');
  const evalInAsync = (expr) => send({ method: 'Runtime.evaluate', params: { expression: expr, awaitPromise: true, returnByValue: true }, 15000 }).then(r => r.result ? r.result.value : (r.error ? { error: r.error.message } : 'ok'));
  await send({ method: 'Page.enable' }, 5000);
  await send({ method: 'Runtime.enable' }, 5000);
  // ensure loaded
  let rs;
  for (let i = 0; i < 10; i++) {
    rs = await evalIn('document.readyState');
    if (rs === 'complete' || rs === 'interactive') break;
  }
  console.log('readyState:', rs);
  const report = (async () => {
    const st = () => ({
      start: document.getElementById('startScreen').hidden,
      test: document.getElementById('testScreen').hidden,
      result: document.getElementById('resultScreen').hidden
    });
    const reportOut = { readyState: document.readyState };
    // 1. start
    document.getElementById('btnStart').click();
    await new Promise(a => setTimeout(a, 250));
    reportOut.afterStart = st();
    reportOut.listCount = document.querySelectorAll('.disc-list').length;
    reportOut.itemCount = document.querySelectorAll('.disc-item').length;
    // 2. advance
    for (let i = 0; i < 8; i++) {
      const fb = document.getElementById('btnFinish');
      if (fb && fb.style.display !== 'none') { reportOut.reachedLast = true; break; }
      const nb = document.getElementById('btnNext');
      if (nb && nb.style.display !== 'none') { nb.click(); await new Promise(a => setTimeout(a, 80)); }
      else { reportOut.stuck = true; break; }
    }
    reportOut.btns = { next: (document.getElementById('btnNext') || { style: { display: 'x' } }).style.display, finish: (document.getElementById('btnFinish') || { style: { display: 'x' } }).style.display };
    // 3. finish
    const fb = document.getElementById('btnFinish');
    if (fb && fb.style.display !== 'none') {
      fb.click();
      await new Promise(a => setTimeout(a, 600));
      reportOut.afterFinish = st();
      const rc = document.getElementById('resultContent');
      reportOut.text = rc ? rc.textContent.replace(/\s+/g, ' ').slice(0, 150) : 'none';
      reportOut.bars = Array.from(document.querySelectorAll('.result-bar__bar i')).map(b => b.style.width);
      reportOut.resultVisible = !document.getElementById('resultScreen').hidden;
    } else {
      reportOut.err = 'finish not shown';
    }
    return reportOut;
  })();
  const out = await evalInAsync(report);
  console.log('REPORT:', JSON.stringify(out, null, 2));
  process.exit(0);
}
main().catch(e => { console.error('FATAL', e.message); process.exit(1); });

